   106|interface NeonAuthUser {
   107|  id: string;
   108|  name?: string;
   109|  email: string;
   110|  emailVerified?: boolean;
   111|}
   112|
   113|interface NeonAuthSession {
   114|  token: string;
   115|}
   116|
   117|interface NeonAuthResponse {
   118|  user: NeonAuthUser;
   119|  session?: NeonAuthSession;
