   123|// ─── Neon Auth Helpers ─────────────────────────────────────
   124|
   125|/** Call Neon Auth REST API. Returns parsed JSON or throws on error. Accepts optional Origin header. */
   126|async function callNeonAuth(
   127|  path: string,
   128|  body: Record<string, unknown>,
   129|  origin?: string
   130|): Promise<NeonAuthResponse> {
   131|  const url = `${NEON_AUTH}${path}`;
   132|  const headers: Record<string, string> = { "Content-Type": "application/json" };
   133|  if (origin) headers["Origin"] = origin;
   134|  const resp = await fetch(url, {
   135|    method: "POST",
   136|    headers,
   137|    body: JSON.stringify(body),
   138|  });
   139|  const data = await resp.json() as Record<string, unknown>;
   140|  if (!resp.ok) {
   141|    const message = (data.message as string) || (data.error as string) || `Auth error (${resp.status})`;
   142|    throw new Error(message);
   143|  }
   144|  return data as unknown as NeonAuthResponse;
   145|}
   146|
   147|/** Create or update a profile in vita_hero.profiles after Neon Auth success. */
   148|async function upsertProfileFromNeonAuth(
   149|  sql: ReturnType<typeof neon>,
   150|  user: NeonAuthUser,
   151|  provider: string
   152|): Promise<{ profileId: string; sessionToken: string }> {
   153|  const profileId = `na_${user.id.slice(0, 24)}`;
   154|  const sessionToken = generateToken();
   155|
   156|  const existing = await sql`
   157|    SELECT id FROM ${sql(SCHEMA)}.profiles WHERE id = ${profileId} LIMIT 1
   158|  `;
   159|
   160|  if (existing.length === 0) {
   161|    await sql`
   162|      INSERT INTO ${sql(SCHEMA)}.profiles
   163|        (id, user_id, name, email, session_token, auth_provider,
   164|         onboarding_complete, is_logged_in)
   165|      VALUES (
   166|        ${profileId}, ${user.id}, ${user.name || user.email.split('@')[0]},
   167|        ${user.email}, ${sessionToken}, ${provider}, true, true
   168|      )
   169|    `;
   170|  } else {
   171|    await sql`
   172|      UPDATE ${sql(SCHEMA)}.profiles
   173|      SET session_token = ${sessionToken}, is_logged_in = true,
   174|          name = ${user.name || user.email.split('@')[0]},
   175|          email = ${user.email}, auth_provider = ${provider}
   176|      WHERE id = ${profileId}
   177|    `;
   178|  }
   179|
   180|  return { profileId, sessionToken };
   181|}
