   183|// ─── Entrypoint ─────────────────────────────────────────────
   184|
   185|export default {
   186|  async fetch(request: Request, env: Env): Promise<Response> {
   187|    if (request.method === "OPTIONS") return cors(new Response(null, { status: 204 }));
   188|
   189|    const url = new URL(request.url);
   190|    const path = url.pathname;
   191|    const dbUrl = env.DATABASE_URL;
   192|
   193|    if (!dbUrl) {
   194|      return json({ error: "DATABASE_URL not configured" }, 500);
   195|    }
   196|
   197|    try {
   198|      const sql = neon(dbUrl);
   199|
   200|      // ── Schema Init (idempotent) ─────────────────────
   201|      try {
   202|        await sql`CREATE SCHEMA IF NOT EXISTS ${sql(SCHEMA)}`;
   203|      } catch { /* schema may already exist */ }
   204|
   205|      try {
   206|        await sql`
   207|          CREATE TABLE IF NOT EXISTS ${sql(SCHEMA)}.profiles (
   208|            id TEXT PRIMARY KEY,
   209|            user_id TEXT,
   210|            phone TEXT,
   211|            name TEXT NOT NULL DEFAULT '',
   212|            email TEXT,
   213|            session_token TEXT,
   214|            auth_provider TEXT,
   215|            onboarding_complete BOOLEAN DEFAULT false,
   216|            is_logged_in BOOLEAN DEFAULT false,
   217|            dark_theme BOOLEAN DEFAULT false,
   218|            locale_code TEXT DEFAULT 'en',
   219|            family_code TEXT DEFAULT '',
   220|            notifications_enabled BOOLEAN DEFAULT true,
   221|            camp_reminders_enabled BOOLEAN DEFAULT true,
   222|            consent_accepted BOOLEAN DEFAULT false,
   223|            consent_declined BOOLEAN DEFAULT false
   224|          )
   225|        `;
   226|      } catch { /* table may already exist */ }
   227|
   228|      try {
   229|        await sql`
   230|          CREATE TABLE IF NOT EXISTS ${sql(SCHEMA)}.phone_otps (
   231|            phone TEXT PRIMARY KEY,
   232|            otp TEXT NOT NULL,
   233|            expires_at TIMESTAMPTZ NOT NULL,
   234|            attempts INT DEFAULT 0
   235|          )
   236|        `;
   237|      } catch { /* table may already exist */ }
   238|
   239|      // ── Health Check ─────────────────────────────────
   240|      if (path === "/ping") {
   241|        const rows = await sql`SELECT 1 AS ok, NOW() AS now`;
   242|        return json({ ok: true, db: rows[0] });
   243|      }
   244|
   245|      // ═══════════════════════════════════════════════════
   246|      // AUTH ENDPOINTS
   247|      // ═══════════════════════════════════════════════════
   248|
   249|      // ── Email/Password Sign-Up ───────────────────────
   250|      if (path === "/api/auth/signup" && request.method === "POST") {
   251|        try {
   252|          const body: Record<string, unknown> = await request.json();
   253|          const name = (body.name as string)?.trim();
   254|          const email = (body.email as string)?.trim();
   255|          const password = body.password as string;
   256|
   257|          if (!name || !email || !password) {
   258|            return json({ error: "name, email, and password are required" }, 400);
   259|          }
   260|          if (password.length < 8) {
   261|            return json({ error: "Password must be at least 8 characters" }, 400);
   262|          }
   263|
   264|          const neonResp = await callNeonAuth("/sign-up/email", { name, email, password });
   265|          const { profileId, sessionToken } = await upsertProfileFromNeonAuth(
   266|            sql, neonResp.user, "EMAIL"
   267|          );
   268|
   269|          return json({
   270|            token: sessionToken,
   271|            profile: {
   272|              id: profileId,
   273|              user_id: neonResp.user.id,
   274|              name: neonResp.user.name || email.split("@")[0],
   275|              email: neonResp.user.email,
   276|              auth_provider: "EMAIL",
   277|            },
   278|          });
   279|        } catch (e) {
   280|          const message = e instanceof Error ? e.message : String(e);
   281|          return json({ error: message }, 400);
   282|        }
   283|      }
   284|
   285|      // ── Email/Password Sign-In ───────────────────────
   286|      if (path === "/api/auth/signin" && request.method === "POST") {
   287|        try {
   288|          const body: Record<string, unknown> = await request.json();
   289|          const email = (body.email as string)?.trim();
   290|          const password = body.password as string;
   291|
   292|          if (!email || !password) {
   293|            return json({ error: "email and password are required" }, 400);
   294|          }
   295|
   296|          const neonResp = await callNeonAuth("/sign-in/email", { email, password });
   297|          const { profileId, sessionToken } = await upsertProfileFromNeonAuth(
   298|            sql, neonResp.user, "EMAIL"
   299|          );
   300|
   301|          return json({
   302|            token: sessionToken,
   303|            profile: {
   304|              id: profileId,
   305|              user_id: neonResp.user.id,
   306|              name: neonResp.user.name || email.split("@")[0],
   307|              email: neonResp.user.email,
   308|              auth_provider: "EMAIL",
   309|            },
   310|          });
   311|        } catch (e) {
   312|          const message = e instanceof Error ? e.message : String(e);
   313|          return json({ error: message }, 401);
   314|        }
   315|      }
   316|
   317|      // ── Google Sign-In (via Neon Auth social) ────────
   318|      if (path === "/api/auth/google" && request.method === "POST") {
   319|        try {
   320|          const body: Record<string, unknown> = await request.json();
   321|          const idToken = body.id_token as string;
   322|          if (!idToken) return json({ error: "Missing id_token" }, 400);
   323|
   324|          const workerOrigin = new URL(request.url).origin;
   325|          const neonResp = await callNeonAuth("/sign-in/social", {
   326|            provider: "google",
   327|            idToken: { token: idToken },
   328|            callbackURL: workerOrigin,
   329|          }, workerOrigin);
   330|
   331|          const { profileId, sessionToken } = await upsertProfileFromNeonAuth(
   332|            sql, neonResp.user, "GOOGLE"
   333|          );
   334|
   335|          return json({
   336|            token: sessionToken,
   337|            profile: {
   338|              id: profileId,
   339|              user_id: neonResp.user.id,
   340|              name: neonResp.user.name || neonResp.user.email.split("@")[0],
   341|              email: neonResp.user.email,
   342|              auth_provider: "GOOGLE",
   343|            },
   344|          });
   345|        } catch (e) {
   346|          const message = e instanceof Error ? e.message : String(e);
   347|          return json({ error: message }, 401);
   348|        }
   349|      }
   350|
   351|      // ── Phone OTP: Send ──────────────────────────────
   352|      if (path === "/api/auth/phone/send" && request.method === "POST") {
   353|        const body: Record<string, unknown> = await request.json();
   354|        const phone = (body.phone as string)?.trim();
   355|        if (!phone) return json({ error: "Missing phone" }, 400);
   356|
   357|        const otp = generateOtp();
   358|        const expiresAt = new Date(Date.now() + OTP_EXPIRY_MINUTES * 60_000);
   359|
   360|        await sql`
   361|          INSERT INTO ${sql(SCHEMA)}.phone_otps (phone, otp, expires_at, attempts)
   362|          VALUES (${phone}, ${otp}, ${expiresAt.toISOString()}, 0)
   363|          ON CONFLICT (phone) DO UPDATE SET
   364|            otp = EXCLUDED.otp,
   365|            expires_at = EXCLUDED.expires_at,
   366|            attempts = 0
   367|        `;
   368|
   369|        const sent = await sendTwilioSms(
   370|          env, phone,
   371|          `Your VitaHero verification code is: ${otp}`
   372|        );
   373|
   374|        return json({ success: sent, note: sent ? undefined : "OTP generated but SMS delivery may be delayed" });
   375|      }
   376|
   377|      // ── Phone OTP: Verify ────────────────────────────
   378|      if (path === "/api/auth/phone/verify" && request.method === "POST") {
   379|        const body: Record<string, unknown> = await request.json();
   380|        const phone = (body.phone as string)?.trim();
   381|        const otp = (body.otp as string)?.trim();
   382|        if (!phone || !otp) return json({ error: "Missing phone or otp" }, 400);
   383|
   384|        const rows = await sql`
   385|          SELECT otp, expires_at, attempts
   386|          FROM ${sql(SCHEMA)}.phone_otps WHERE phone = ${phone} LIMIT 1
   387|        `;
   388|
   389|        if (rows.length === 0) {
   390|          return json({ error: "No OTP requested for this number" }, 400);
   391|        }
   392|
   393|        const record = rows[0];
   394|        if (record.attempts >= OTP_MAX_ATTEMPTS) {
   395|          return json({ error: "Too many attempts. Request a new OTP." }, 429);
   396|        }
   397|        if (new Date(record.expires_at) < new Date()) {
   398|          return json({ error: "OTP expired. Request a new one." }, 410);
   399|        }
   400|
   401|        // Increment attempts
   402|        await sql`
   403|          UPDATE ${sql(SCHEMA)}.phone_otps
   404|          SET attempts = attempts + 1 WHERE phone = ${phone}
   405|        `;
   406|
   407|        if (record.otp !== otp) {
   408|          return json({ error: "Invalid OTP" }, 401);
   409|        }
   410|
   411|        // OTP verified — clean up
   412|        await sql`DELETE FROM ${sql(SCHEMA)}.phone_otps WHERE phone = ${phone}`;
   413|
   414|        // Create or update profile
   415|        const profileId = `ph_${phone.replace(/\D/g, "").slice(-10)}`;
   416|        const sessionToken = generateToken();
   417|
   418|        const existing = await sql`
   419|          SELECT id FROM ${sql(SCHEMA)}.profiles WHERE id = ${profileId} LIMIT 1
   420|        `;
   421|
   422|        if (existing.length === 0) {
   423|          await sql`
   424|            INSERT INTO ${sql(SCHEMA)}.profiles
   425|              (id, phone, name, session_token, auth_provider,
   426|               onboarding_complete, is_logged_in)
   427|            VALUES (
   428|              ${profileId}, ${phone}, 'Parent', ${sessionToken}, 'PHONE',
   429|              true, true
   430|            )
   431|          `;
   432|        } else {
   433|          await sql`
   434|            UPDATE ${sql(SCHEMA)}.profiles
   435|            SET session_token = ${sessionToken}, is_logged_in = true, phone = ${phone}
   436|            WHERE id = ${profileId}
   437|          `;
   438|        }
   439|
   440|        // Also delete any old OTPs
   441|        try {
   442|          await sql`DELETE FROM ${sql(SCHEMA)}.phone_otps WHERE expires_at < NOW()`;
   443|        } catch { /* best effort */ }
   444|
   445|        return json({
   446|          token: sessionToken,
   447|          profile: {
   448|            id: profileId,
   449|            phone,
   450|            name: "Parent",
   451|            auth_provider: "PHONE",
   452|          },
   453|        });
   454|      }
   455|
   456|      // ── Verify Session Token ─────────────────────────
   457|      if (path === "/api/auth/me" && request.method === "GET") {
   458|        const token = extractToken(request);
   459|        const session = await authenticateSession(sql, token);
   460|        if (!session) return json({ error: "Invalid or expired session" }, 401);
   461|
   462|        const profile = await sql`
   463|          SELECT * FROM ${sql(SCHEMA)}.profiles WHERE id = ${session.profileId} LIMIT 1
   464|        `;
   465|        return json(profile[0] || null);
   466|      }
   467|
   468|      // ── Logout ───────────────────────────────────────
   469|      if (path === "/api/auth/logout" && request.method === "POST") {
   470|        const token = extractToken(request);
   471|        if (token) {
   472|          await sql`
   473|            UPDATE ${sql(SCHEMA)}.profiles
   474|            SET session_token = NULL, is_logged_in = false
   475|            WHERE session_token = ${token}
   476|          `;
   477|        }
   478|        return json({ success: true });
   479|      }
   480|
   481|      // ═══════════════════════════════════════════════════
   482|      // AUTHENTICATED DATA ENDPOINTS
   483|      // ═══════════════════════════════════════════════════
   484|
   485|      const token = extractToken(request);
   486|      const session = await authenticateSession(sql, token);
   487|
   488|      // ═══════════════════════════════════════════════════
   489|      // Profiles
   490|      // ═══════════════════════════════════════════════════
   491|
   492|      if (path === "/api/profiles" && request.method === "GET") {
   493|        if (!session) return json({ error: "Unauthorized" }, 401);
   494|        const rows = await sql`SELECT * FROM ${sql(SCHEMA)}.profiles WHERE id = ${session.profileId} LIMIT 1`;
   495|        // Don't leak session token
   496|        if (rows[0]) delete rows[0].session_token;
   497|        return json(rows[0] || null);
   498|      }
   499|
   500|      if (path === "/api/profiles" && request.method === "POST") {
   501|        if (!session) return json({ error: "Unauthorized" }, 401);
   502|        const body: Record<string, unknown> = await request.json();
   503|        const row = await sql`
   504|          INSERT INTO ${sql(SCHEMA)}.profiles
   505|            (id, user_id, phone, name, email,
   506|             onboarding_complete, is_logged_in,
