   509|             consent_accepted, consent_declined,
   510|             auth_provider, session_token)
   511|          VALUES (
   512|            ${session.profileId},
   513|            ${(body.user_id as string) || session.userId},
   514|            ${(body.phone as string) || null},
   515|            ${(body.name as string) || session.name},
   516|            ${(body.email as string) || null},
   517|            ${(body.onboarding_complete as boolean) || false},
   518|            ${(body.is_logged_in as boolean) || false},
   519|            ${(body.dark_theme as boolean) || false},
   520|            ${(body.locale_code as string) || "en"},
   521|            ${(body.family_code as string) || ""},
   522|            ${(body.notifications_enabled as boolean) ?? true},
   523|            ${(body.camp_reminders_enabled as boolean) ?? true},
   524|            ${(body.consent_accepted as boolean) || false},
   525|            ${(body.consent_declined as boolean) || false},
   526|            ${(body.auth_provider as string) || "GOOGLE"},
   527|            ${token}
   528|          )
   529|          ON CONFLICT (id) DO UPDATE SET
   530|            user_id = EXCLUDED.user_id, phone = EXCLUDED.phone,
   531|            name = EXCLUDED.name, email = EXCLUDED.email,
   532|            onboarding_complete = EXCLUDED.onboarding_complete,
   533|            is_logged_in = EXCLUDED.is_logged_in,
   534|            dark_theme = EXCLUDED.dark_theme,
   535|            locale_code = EXCLUDED.locale_code,
   536|            family_code = EXCLUDED.family_code,
   537|            notifications_enabled = EXCLUDED.notifications_enabled,
   538|            camp_reminders_enabled = EXCLUDED.camp_reminders_enabled,
   539|            consent_accepted = EXCLUDED.consent_accepted,
   540|            consent_declined = EXCLUDED.consent_declined,
   541|            auth_provider = EXCLUDED.auth_provider
   542|          RETURNING *
   543|        `;
   544|        if (row[0]) delete row[0].session_token;
   545|        return json(row[0], 201);
   546|      }
   547|
   548|      // ═══════════════════════════════════════════════════
   549|      // Kids
   550|      // ═══════════════════════════════════════════════════
   551|
   552|      if (path === "/api/kids" && request.method === "GET") {
   553|        if (!session) return json({ error: "Unauthorized" }, 401);
   554|        const profileId = session.profileId;
   555|        const rows = await sql`SELECT * FROM ${sql(SCHEMA)}.kids WHERE profile_id = ${profileId} ORDER BY name`;
   556|        return json(rows);
   557|      }
   558|
   559|      if (path === "/api/kids" && request.method === "POST") {
   560|        if (!session) return json({ error: "Unauthorized" }, 401);
   561|        const body: Record<string, unknown> = await request.json();
   562|        const row = await sql`
   563|          INSERT INTO ${sql(SCHEMA)}.kids
   564|            (id, profile_id, user_id, name, age, gender, school, grade,
   565|             height_cm, weight_kg, avatar_color, overall_score, dental,
